H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
const m = P.m, b = P.b;
v.fn(x => m * x + b, { color: H.colors.accent, width: 3 });
v.dot(0, b, { r: 6, fill: H.colors.warn });
v.line(0, b, 2, b, { color: H.colors.good, width: 2, dash: [5, 5] });
v.line(2, b, 2, m * 2 + b, { color: H.colors.violet, width: 2, dash: [5, 5] });
const xs = 6 * Math.sin(t * 0.6);
v.dot(xs, m * xs + b, { r: 6, fill: H.colors.accent2 });
H.text("y = m·x + b", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(2) + "    b = " + b.toFixed(2), 24, 52, { color: H.colors.sub, size: 14 });
H.legend([{ label: "rise", color: H.colors.violet }, { label: "run", color: H.colors.good }], H.W - 150, 28);

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
const m1 = P.m1, b1 = P.b1, m2 = P.m2, b2 = P.b2;
v.fn(x => m1 * x + b1, { color: H.colors.accent, width: 3 });
v.fn(x => m2 * x + b2, { color: H.colors.accent2, width: 3 });
H.text("System: two lines", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
if (Math.abs(m1 - m2) > 1e-6) {
  const xi = (b2 - b1) / (m1 - m2), yi = m1 * xi + b1;
  H.circle(v.X(xi), v.Y(yi), 6 + Math.sin(t * 3), { fill: H.colors.warn });
  H.text("solution  (" + xi.toFixed(2) + ", " + yi.toFixed(2) + ")", 24, 52, { color: H.colors.good, size: 14 });
} else {
  H.text(Math.abs(b1 - b2) < 1e-6 ? "same line — infinitely many solutions" : "parallel lines — no solution", 24, 52, { color: H.colors.warn, size: 14 });
}
H.legend([{ label: "line 1", color: H.colors.accent }, { label: "line 2", color: H.colors.accent2 }], H.W - 150, 28);

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -4, yMax: 10 });
v.grid(); v.axes();
const a = P.a, h = P.h, k = P.k;
v.fn(x => a * Math.abs(x - h) + k, { color: H.colors.accent, width: 3 });
v.dot(h, k, { r: 7, fill: H.colors.warn });
const xs = h + 5 * Math.sin(t * 0.7);
v.dot(xs, a * Math.abs(xs - h) + k, { r: 6, fill: H.colors.accent2 });
H.text("y = a|x − h| + k", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("vertex (" + h.toFixed(1) + ", " + k.toFixed(1) + ")    slope ±" + Math.abs(a).toFixed(1), 24, 52, { color: H.colors.sub, size: 14 });

H.background();
const v = H.plot2d({ xMin: -1, xMax: 8, yMin: -1, yMax: 12 });
v.grid(); v.axes();
const a = P.a, b = Math.max(0.05, P.b);
v.fn(x => a * Math.pow(b, x), { color: H.colors.accent, width: 3 });
const xs = (t % 8);
v.dot(xs, a * Math.pow(b, xs), { r: 6, fill: H.colors.warn });
H.text("y = a · bˣ", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a = " + a.toFixed(2) + "   b = " + b.toFixed(2) + (b > 1 ? "   (growth)" : "   (decay)"), 24, 52, { color: H.colors.sub, size: 14 });

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -4, yMax: 12 });
v.grid(); v.axes();
const a = P.a, h = P.h, k = P.k;
v.fn(x => a * (x - h) * (x - h) + k, { color: H.colors.accent, width: 3 });
v.line(h, -4, h, 12, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
v.dot(h, k, { r: 7, fill: H.colors.warn });
const xs = h + 4 * Math.sin(t * 0.7);
v.dot(xs, a * (xs - h) * (xs - h) + k, { r: 6, fill: H.colors.accent2 });
H.text("y = a(x − h)² + k", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("vertex (" + h.toFixed(1) + ", " + k.toFixed(1) + ")    a = " + a.toFixed(2), 24, 52, { color: H.colors.sub, size: 14 });

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -10, yMax: 10 });
v.grid(); v.axes();
const a = P.a, b = P.b, c = P.c;
v.fn(x => a * x * x + b * x + c, { color: H.colors.accent, width: 3 });
const disc = b * b - 4 * a * c;
if (disc >= 0 && Math.abs(a) > 1e-6) {
  const r1 = (-b + Math.sqrt(disc)) / (2 * a), r2 = (-b - Math.sqrt(disc)) / (2 * a);
  v.dot(r1, 0, { r: 6, fill: H.colors.good });
  v.dot(r2, 0, { r: 6, fill: H.colors.good });
}
const xs = 5 * Math.sin(t * 0.6);
v.dot(xs, a * xs * xs + b * xs + c, { r: 5, fill: H.colors.accent2 });
H.text("y = ax² + bx + c", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const verdict = disc > 1e-9 ? " → 2 real roots" : Math.abs(disc) <= 1e-9 ? " → 1 real root" : " → no real roots";
H.text("b² − 4ac = " + disc.toFixed(2) + verdict, 24, 52, { color: H.colors.sub, size: 13 });

H.background();
const v = H.plot2d({ xMin: -3, xMax: 3, yMin: -10, yMax: 10 });
v.grid(); v.axes();
const a = P.a, n = Math.max(1, Math.round(P.n));
v.fn(x => a * Math.pow(x, n), { color: H.colors.accent, width: 3 });
const xs = 2.5 * Math.sin(t * 0.6);
v.dot(xs, a * Math.pow(xs, n), { r: 6, fill: H.colors.warn });
const even = n % 2 === 0;
H.text("y = a · xⁿ   (end behavior)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a = " + a.toFixed(1) + "   n = " + n + (even ? "   even: ends match" : "   odd: ends oppose"), 24, 52, { color: H.colors.sub, size: 13 });

H.background();
const v = H.plot2d({ xMin: -6, xMax: 6, yMin: -6, yMax: 6 });
v.grid(); v.axes();
const b = Math.min(5, Math.max(1.2, P.b));
v.line(-6, -6, 6, 6, { color: H.colors.violet, width: 1.5, dash: [5, 5] });
v.fn(x => Math.pow(b, x), { color: H.colors.accent, width: 3 });
v.fn(x => (x > 0 ? Math.log(x) / Math.log(b) : NaN), { color: H.colors.accent2, width: 3 });
const xs = 2.4 * Math.sin(t * 0.6);
v.dot(xs, Math.pow(b, xs), { r: 5, fill: H.colors.warn });
H.text("y = bˣ  and its inverse  y = log_b(x)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("base b = " + b.toFixed(2) + "  —  mirror images across y = x", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "bˣ", color: H.colors.accent }, { label: "log_b x", color: H.colors.accent2 }, { label: "y = x", color: H.colors.violet }], H.W - 150, 28);

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -6, yMax: 10 });
v.grid(); v.axes();
const a = P.a, b = Math.max(0.1, P.b), h = P.h, k = P.k;
const base = (x) => Math.sin(x);
v.fn(base, { color: H.colors.sub, width: 1.5 });
v.fn(x => a * base(b * (x - h)) + k, { color: H.colors.accent, width: 3 });
const xs = 6 * Math.sin(t * 0.6);
v.dot(xs, a * base(b * (xs - h)) + k, { r: 6, fill: H.colors.warn });
H.text("y = a · f(b(x − h)) + k", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a=" + a.toFixed(1) + "  b=" + b.toFixed(1) + "  h=" + h.toFixed(1) + "  k=" + k.toFixed(1), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "parent  f(x)=sin x", color: H.colors.sub }, { label: "transformed", color: H.colors.accent }], H.W - 230, 28);

H.background();
const cx = H.W * 0.5, cy = H.H * 0.52, R = Math.min(H.W, H.H) * 0.3;
const ang = P.deg * Math.PI / 180;
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 1.5 });
H.line(cx - R - 12, cy, cx + R + 12, cy, { color: H.colors.axis, width: 1 });
H.line(cx, cy - R - 12, cx, cy + R + 12, { color: H.colors.axis, width: 1 });
const px = cx + R * Math.cos(ang), py = cy - R * Math.sin(ang);
H.line(cx, cy, px, py, { color: H.colors.accent2, width: 2 });
H.line(px, py, px, cy, { color: H.colors.good, width: 2, dash: [4, 4] });
H.line(px, py, cx, py, { color: H.colors.accent, width: 2, dash: [4, 4] });
H.circle(px, py, 6 + Math.sin(t * 3), { fill: H.colors.warn });
H.text("Unit circle: (cos θ, sin θ)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("θ = " + P.deg.toFixed(0) + "°    cos θ = " + Math.cos(ang).toFixed(2) + "    sin θ = " + Math.sin(ang).toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "cos θ", color: H.colors.accent }, { label: "sin θ", color: H.colors.good }], H.W - 150, 28);

H.background();
const v = H.plot2d({ xMin: -Math.PI, xMax: 3 * Math.PI, yMin: -6, yMax: 6 });
v.grid(); v.axes();
const A = P.A, B = Math.max(0.1, P.B), C = P.C, D = P.D;
v.line(-Math.PI, D, 3 * Math.PI, D, { color: H.colors.violet, width: 1.5, dash: [5, 5] });
v.fn(x => A * Math.sin(B * (x - C)) + D, { color: H.colors.accent, width: 3 });
const xs = -Math.PI + ((t * 0.8) % (4 * Math.PI));
v.dot(xs, A * Math.sin(B * (xs - C)) + D, { r: 6, fill: H.colors.warn });
H.text("y = A·sin(B(x − C)) + D", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("A = " + A.toFixed(1) + "   period = " + (2 * Math.PI / B).toFixed(2) + "   C = " + C.toFixed(1) + "   D = " + D.toFixed(1), 24, 52, { color: H.colors.sub, size: 12 });

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -6, yMax: 6 });
v.grid(); v.axes();
const a = Math.max(0.5, P.a), b = Math.max(0.5, P.b);
const pts = [];
for (let i = 0; i <= 90; i++) { const th = i / 90 * H.TAU; pts.push([a * Math.cos(th), b * Math.sin(th)]); }
v.path(pts, { color: H.colors.accent, width: 3, close: true });
const c = Math.sqrt(Math.abs(a * a - b * b));
if (a >= b) { v.dot(c, 0, { r: 5, fill: H.colors.warn }); v.dot(-c, 0, { r: 5, fill: H.colors.warn }); }
else { v.dot(0, c, { r: 5, fill: H.colors.warn }); v.dot(0, -c, { r: 5, fill: H.colors.warn }); }
const th = t * 0.8;
v.dot(a * Math.cos(th), b * Math.sin(th), { r: 6, fill: H.colors.accent2 });
H.text("Ellipse:  x²/a² + y²/b² = 1", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a = " + a.toFixed(1) + "   b = " + b.toFixed(1) + "   foci at c = " + c.toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });

H.background();
// Absolute value equation:  |x - h| = d   (distance from h equals d)
// Solutions are the two points h - d and h + d on the number line.
const h = P.h, d = Math.abs(P.d);
H.text("Absolute value equation:  |x − h| = d", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const nSols = d > 1e-9 ? 2 : (Math.abs(d) <= 1e-9 ? 1 : 0);
H.text("|x − " + h.toFixed(1) + "| = " + d.toFixed(1) + "   means: x is distance " + d.toFixed(1) + " from " + h.toFixed(1), 24, 52, { color: H.colors.sub, size: 13 });
const W = H.W, Ht = H.H;
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -2, yMax: 2, box: { x: 50, y: Ht * 0.5, w: W - 100, h: 90 } });
v.line(-10, 0, 10, 0, { color: H.colors.axis, width: 2 });
for (let i = -10; i <= 10; i++) {
  v.line(i, -0.22, i, 0.22, { color: H.colors.grid, width: 1 });
  if (i % 2 === 0) v.text(String(i), i, -0.95, { color: H.colors.sub, size: 11, align: "center" });
}
// center h
v.dot(h, 0, { r: 5, fill: H.colors.violet });
v.text("h = " + h.toFixed(1), h, 1.5, { color: H.colors.violet, size: 12, align: "center" });
const x1 = h - d, x2 = h + d;
// distance brackets from h out to each solution
v.line(h, 0.55, x1, 0.55, { color: H.colors.accent, width: 3 });
v.line(h, -0.55, x2, -0.55, { color: H.colors.accent2, width: 3 });
v.text("dist " + d.toFixed(1), (h + x1) / 2, 1.05, { color: H.colors.accent, size: 11, align: "center" });
v.text("dist " + d.toFixed(1), (h + x2) / 2, -1.25, { color: H.colors.accent2, size: 11, align: "center" });
// solution dots
v.dot(x1, 0, { r: 7, fill: H.colors.good });
v.dot(x2, 0, { r: 7, fill: H.colors.good });
v.text("x = " + x1.toFixed(1), x1, 1.5, { color: H.colors.good, size: 12, align: "center" });
v.text("x = " + x2.toFixed(1), x2, 1.5, { color: H.colors.good, size: 12, align: "center" });
// animated probe: a dot sweeping the line; its bar grows = |x - h|, glows when it equals d
const xp = h + (d + 3) * Math.sin(t * 0.8);
const dist = Math.abs(xp - h);
const hit = Math.abs(dist - d) < 0.12;
v.dot(xp, 0, { r: hit ? 8 + Math.sin(t * 8) : 5, fill: hit ? H.colors.warn : H.colors.accent });
H.text("|x − h| sweeps:  current |x − " + h.toFixed(1) + "| = " + dist.toFixed(2) + (hit ? "  = d  ✓ solution!" : ""), 24, Ht * 0.5 - 22, { color: hit ? H.colors.warn : H.colors.sub, size: 13 });
H.text(nSols === 2 ? "two solutions" : nSols === 1 ? "one solution (x = h)" : "no solution (d < 0)", 24, Ht * 0.5 + 90, { color: H.colors.good, size: 13, weight: 700 });

H.background();
// Absolute value inequality:  |x - h| < d  (or > d, toggle with `gt`).
// Graph y = |x - h| and the line y = d; the solution is where the V is below
// (or above) the line. "less than" -> the BETWEEN band; "greater" -> OUTSIDE.
const h = P.h, d = Math.abs(P.d), gt = P.gt >= 0.5;
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -1, yMax: 9 });
v.grid(); v.axes();
const x1 = h - d, x2 = h + d;
// draw solution band on the axis (y just above 0)
if (!gt) {
  v.line(x1, 0.18, x2, 0.18, { color: H.colors.good, width: 8 });
} else {
  v.line(-10, 0.18, x1, 0.18, { color: H.colors.good, width: 8 });
  v.line(x2, 0.18, 10, 0.18, { color: H.colors.good, width: 8 });
}
// the V and the threshold line
v.line(-10, d, 10, d, { color: H.colors.violet, width: 2, dash: [6, 6] });
v.fn(x => Math.abs(x - h), { color: H.colors.accent, width: 3 });
v.dot(h, 0, { r: 6, fill: H.colors.accent2 });
// boundary points where V crosses the line
v.dot(x1, d, { r: 6, fill: H.colors.warn });
v.dot(x2, d, { r: 6, fill: H.colors.warn });
v.text("x = " + x1.toFixed(1), x1, d + 0.7, { color: H.colors.warn, size: 11, align: "center" });
v.text("x = " + x2.toFixed(1), x2, d + 0.7, { color: H.colors.warn, size: 11, align: "center" });
// animated probe walking the V; turns green inside the solution set
const xp = h + (d + 4) * Math.sin(t * 0.7);
const yp = Math.abs(xp - h);
const inSol = gt ? (yp > d) : (yp < d);
v.dot(xp, yp, { r: 6 + (inSol ? Math.sin(t * 5) : 0), fill: inSol ? H.colors.good : H.colors.sub });
v.line(xp, 0, xp, yp, { color: inSol ? H.colors.good : H.colors.sub, width: 1.5, dash: [3, 3] });
H.text("Absolute value inequality:  |x − h| " + (gt ? ">" : "<") + " d", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const setText = gt ? ("x < " + x1.toFixed(1) + "  or  x > " + x2.toFixed(1) + "   (outside)")
                   : (x1.toFixed(1) + " < x < " + x2.toFixed(1) + "   (between)");
H.text("h = " + h.toFixed(1) + "   d = " + d.toFixed(1) + "   →   " + setText, 24, 52, { color: H.colors.sub, size: 13 });
H.text("probe x = " + xp.toFixed(2) + ":  |x − h| = " + yp.toFixed(2) + (inSol ? "  ✓ in solution" : "  ✗ not"), 24, 76, { color: inSol ? H.colors.good : H.colors.sub, size: 13 });
H.legend([{ label: "y = |x − h|", color: H.colors.accent }, { label: "y = d", color: H.colors.violet }, { label: "solution set", color: H.colors.good }], H.W - 190, 100);

H.background();
const w = H.W, hh = H.H;
const a = Math.round(P.a), b = Math.round(P.b), c = Math.round(P.c), d = Math.round(P.d);
// Combine like terms in  a x + c + b x + d  ->  (a+b) x + (c+d)
const xc = a + b, kc = c + d;
H.text("Combine like terms:  ax + c + bx + d", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Only matching kinds add: x-tiles join x-tiles, units join units.", 24, 54, { color: H.colors.sub, size: 13 });
// original expression with x-terms in accent, constants in accent2
H.text(a + "x", 60, 96, { color: H.colors.accent, size: 22, weight: 700 });
H.text("+ " + c, 110, 96, { color: H.colors.accent2, size: 22, weight: 700 });
H.text("+ " + b + "x", 168, 96, { color: H.colors.accent, size: 22, weight: 700 });
H.text("+ " + d, 234, 96, { color: H.colors.accent2, size: 22, weight: 700 });
// tile model: each x-tile a tall bar, each unit a small square. animate a gather.
const gather = (Math.sin(t * 0.8) + 1) / 2; // 0..1 pulse: spread <-> grouped
const baseY = 250, tileW = 26, gap = 6;
// x tiles (a then b) slide together
let xi = 0;
const total = a + b;
for (let i = 0; i < total; i++) {
  const spreadX = 70 + i * (tileW + gap) + (i >= a ? 60 : 0); // gap between the two groups when spread
  const groupX = 70 + i * (tileW + gap);
  const tx = H.lerp(spreadX, groupX, gather);
  H.rect(tx, baseY - 70, tileW, 70, { fill: H.colors.accent, stroke: H.colors.bg, width: 1, radius: 3 });
  xi = tx + tileW;
}
H.text("x-tiles", 70, baseY + 18, { color: H.colors.accent, size: 13 });
H.text("count = " + xc, 70, baseY + 36, { color: H.colors.sub, size: 12 });
// unit tiles on the right
const ux0 = w * 0.6;
const totalU = c + d;
for (let i = 0; i < totalU; i++) {
  const spreadX = ux0 + i * (tileW + gap) + (i >= c ? 50 : 0);
  const groupX = ux0 + i * (tileW + gap);
  const tx = H.lerp(spreadX, groupX, gather);
  H.rect(tx, baseY - 26, tileW, 26, { fill: H.colors.accent2, stroke: H.colors.bg, width: 1, radius: 3 });
}
H.text("unit tiles", ux0, baseY + 18, { color: H.colors.accent2, size: 13 });
H.text("count = " + kc, ux0, baseY + 36, { color: H.colors.sub, size: 12 });
// result
H.rect(50, baseY + 60, w - 100, 56, { fill: "#13243f", stroke: H.colors.accent, width: 2, radius: 10 });
H.text("= " + xc + "x + " + kc, 70, baseY + 96, { color: H.colors.good, size: 24, weight: 700 });
H.text("(" + a + "+" + b + ")x = " + xc + "x ,  (" + c + "+" + d + ") = " + kc, 24, hh - 22, { color: H.colors.sub, size: 13 });

H.background();
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -3, yMax: 3 });
v.grid({ stepY: 100 }); v.axes({ stepY: 100 });
let lo = P.lo, hi = P.hi;
if (lo > hi) { const tmp = lo; lo = hi; hi = tmp; }
const isAnd = P.mode < 0.5;
if (isAnd) {
  v.line(lo, 0, hi, 0, { color: H.colors.good, width: 6 });
} else {
  v.line(-10, 0, lo, 0, { color: H.colors.good, width: 6 });
  v.line(hi, 0, 10, 0, { color: H.colors.good, width: 6 });
}
v.circle(lo, 0, 8, { stroke: H.colors.warn, width: 3, fill: H.colors.bg });
v.circle(hi, 0, 8, { stroke: H.colors.warn, width: 3, fill: H.colors.bg });
v.text("lo", lo - 0.2, -0.9, { color: H.colors.warn, size: 12 });
v.text("hi", hi - 0.2, -0.9, { color: H.colors.warn, size: 12 });
const xs = 9 * Math.sin(t * 0.6);
const inBand = xs > lo && xs < hi;
const ok = isAnd ? inBand : !inBand;
v.dot(xs, 0, { r: 7, fill: ok ? H.colors.good : H.colors.sub });
H.text("Compound: " + (isAnd ? "lo < x < hi   (AND / between)" : "x < lo  OR  x > hi   (outside)"), 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("lo = " + lo.toFixed(1) + "   hi = " + hi.toFixed(1) + "   test x = " + xs.toFixed(2) + "  ->  " + (ok ? "in the solution" : "not a solution"), 24, 52, { color: H.colors.sub, size: 12 });

H.background();
