H.legend([{ label: "x-intercept", color: H.colors.good }, { label: "y-intercept", color: H.colors.warn }], H.W - 180, 28);

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
const m1 = P.m1, b1 = P.b1, m2 = P.m2, b2 = P.b2;
v.fn(x => m1 * x + b1, { color: H.colors.accent, width: 3 });
v.fn(x => m2 * x + b2, { color: H.colors.accent2, width: 3 });
H.text("Solve a system by graphing", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const par = Math.abs(m1 - m2) < 1e-6;
if (!par) {
  const xi = (b2 - b1) / (m1 - m2), yi = m1 * xi + b1;
  const xt = -7 + ((t * 1.5) % 14);
  v.dot(xt, m1 * xt + b1, { r: 5, fill: H.colors.accent });
  v.dot(xt, m2 * xt + b2, { r: 5, fill: H.colors.accent2 });
  v.line(xi, -8, xi, yi, { color: H.colors.good, width: 1.5, dash: [4, 4] });
  v.line(-8, yi, xi, yi, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
  v.circle(xi, yi, 7 + 2 * Math.sin(t * 3), { stroke: H.colors.warn, width: 2.5 });
  v.dot(xi, yi, { r: 5, fill: H.colors.warn });
  H.text("they cross at  (" + xi.toFixed(2) + ", " + yi.toFixed(2) + ")  <-  the solution", 24, 52, { color: H.colors.good, size: 13 });
} else {
  const sameLine = Math.abs(b1 - b2) < 1e-6;
  const xt = -7 + ((t * 1.5) % 14);
  v.dot(xt, m1 * xt + b1, { r: 5, fill: H.colors.accent });
  H.text(sameLine ? "same line  ->  infinitely many solutions" : "parallel lines  ->  no solution", 24, 52, { color: H.colors.warn, size: 13 });
}
H.legend([{ label: "y = m1 x + b1", color: H.colors.accent }, { label: "y = m2 x + b2", color: H.colors.accent2 }], H.W - 170, 28);

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
// System:  a1*x + y = c1   and   a2*x + y = c2   (both already isolating y for the plot)
const a1 = P.a1, c1 = P.c1, a2 = P.a2, c2 = P.c2;
// y = c1 - a1*x   and   y = c2 - a2*x
v.fn(x => c1 - a1 * x, { color: H.colors.accent, width: 3 });
v.fn(x => c2 - a2 * x, { color: H.colors.accent2, width: 3 });
H.text("Elimination: subtract equations to cancel y", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
// Subtracting eq2 from eq1 cancels the +y term: (a1-a2)x = c1 - c2.
if (Math.abs(a1 - a2) > 1e-6) {
  const xi = (c1 - c2) / (a1 - a2), yi = c1 - a1 * xi;
  // animate the "subtraction" as a shrinking gap between the two lines' y at a swept x
  const xs = 6 * Math.sin(t * 0.7);
  const y1 = c1 - a1 * xs, y2 = c2 - a2 * xs;
  v.line(xs, y1, xs, y2, { color: H.colors.violet, width: 2 });
  v.dot(xs, y1, { r: 4, fill: H.colors.accent });
  v.dot(xs, y2, { r: 4, fill: H.colors.accent2 });
  H.circle(v.X(xi), v.Y(yi), 6 + 1.5 * Math.sin(t * 3), { fill: H.colors.warn });
  H.text("(a1 − a2)x = c1 − c2  →  x = " + xi.toFixed(2) + ",  y = " + yi.toFixed(2), 24, 52, { color: H.colors.good, size: 13 });
} else {
  H.text("a1 = a2: y-terms cancel AND x-terms cancel — no unique x", 24, 52, { color: H.colors.warn, size: 13 });
}
H.legend([{ label: "eq 1", color: H.colors.accent }, { label: "eq 2", color: H.colors.accent2 }, { label: "gap (subtract)", color: H.colors.violet }], H.W - 175, 28);

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
// Two inequalities:  y >= m1*x + b1   AND   y <= m2*x + b2
const m1 = P.m1, b1 = P.b1, m2 = P.m2, b2 = P.b2;
// Shade the feasible region by sampling a grid of test points.
const step = 0.7;
for (let x = -8; x <= 8; x += step) {
  for (let y = -8; y <= 8; y += step) {
    const ok1 = y >= m1 * x + b1;
    const ok2 = y <= m2 * x + b2;
    if (ok1 && ok2) {
      // pulse the overlap so the region "breathes"
      const r = 2.3 + 0.8 * Math.sin(t * 2 + x + y);
      H.circle(v.X(x), v.Y(y), r, { fill: "rgba(103,232,176,0.45)" });
    }
  }
}
// boundary lines
v.fn(x => m1 * x + b1, { color: H.colors.accent, width: 2.5 });
v.fn(x => m2 * x + b2, { color: H.colors.accent2, width: 2.5 });
// a roaming test point that lights up when it's INSIDE the solution set
const tx = 6 * Math.sin(t * 0.6), ty = 5 * Math.sin(t * 0.9 + 1);
const inside = (ty >= m1 * tx + b1) && (ty <= m2 * tx + b2);
v.dot(tx, ty, { r: 6, fill: inside ? H.colors.good : H.colors.warn });
H.text("System of inequalities: shaded = satisfies BOTH", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("test (" + tx.toFixed(1) + ", " + ty.toFixed(1) + ") is " + (inside ? "INSIDE (a solution)" : "outside"), 24, 52, { color: inside ? H.colors.good : H.colors.warn, size: 13 });
H.legend([{ label: "y ≥ m1·x+b1", color: H.colors.accent }, { label: "y ≤ m2·x+b2", color: H.colors.accent2 }], H.W - 185, 28);

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
// Same slope m for both lines; gap d slides line 2 vertically.
const m = P.m, d = P.d;
const b1 = 1;            // line 1 fixed intercept
const b2 = 1 + d;        // line 2 intercept; d = 0 -> identical, d != 0 -> parallel
v.fn(x => m * x + b1, { color: H.colors.accent, width: 3 });
v.fn(x => m * x + b2, { color: H.colors.accent2, width: 3 });
H.text("Same slope: parallel (no solution) or identical (infinite)", 24, 30, { color: H.colors.ink, size: 15, weight: 700 });
// animate a dot riding line 1; its vertical distance to line 2 is constant = |d|
const xs = 6 * Math.sin(t * 0.7);
v.dot(xs, m * xs + b1, { r: 5, fill: H.colors.accent });
v.line(xs, m * xs + b1, xs, m * xs + b2, { color: H.colors.violet, width: 2, dash: [4, 4] });
if (Math.abs(d) < 1e-6) {
  H.text("d = 0  →  SAME line: every point works (infinitely many)", 24, 52, { color: H.colors.good, size: 13 });
} else {
  H.text("d = " + d.toFixed(1) + "  →  parallel, gap stays " + Math.abs(d).toFixed(1) + ": NO solution", 24, 52, { color: H.colors.warn, size: 13 });
}
H.legend([{ label: "line 1", color: H.colors.accent }, { label: "line 2", color: H.colors.accent2 }, { label: "gap = |d|", color: H.colors.violet }], H.W - 165, 28);

H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
const m = P.m, b = P.b, c = P.c;
// Line 1 (already solved for y):  y = m*x + b
v.fn(x => m * x + b, { color: H.colors.accent, width: 3 });
// Line 2 is the horizontal "what we substitute INTO":  x = c  (a vertical line),
// but to keep it a real system we use the second equation  y = -x + c  here.
v.fn(x => -x + c, { color: H.colors.accent2, width: 3 });
H.text("Substitution: put y = m·x + b into the 2nd equation", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
if (Math.abs(m + 1) > 1e-6) {
  // solve m*x + b = -x + c  ->  x = (c - b)/(m + 1)
  const xi = (c - b) / (m + 1), yi = m * xi + b;
  // animated vertical "drop" showing the substituted x-value being found
  const sweep = xi * (0.5 + 0.5 * Math.sin(t * 1.2));
  v.line(sweep, 0, sweep, m * sweep + b, { color: H.colors.violet, width: 2, dash: [4, 4] });
  v.dot(sweep, 0, { r: 5, fill: H.colors.violet });
  H.circle(v.X(xi), v.Y(yi), 6 + 1.5 * Math.sin(t * 3), { fill: H.colors.warn });
  v.line(xi, 0, xi, yi, { color: H.colors.good, width: 2, dash: [3, 3] });
  H.text("solve for x: x = (c − b)/(m + 1) = " + xi.toFixed(2) + ",  y = " + yi.toFixed(2), 24, 52, { color: H.colors.good, size: 13 });
} else {
  H.text("m = −1: lines parallel — substitution gives no x", 24, 52, { color: H.colors.warn, size: 13 });
}
H.legend([{ label: "y = m·x + b", color: H.colors.accent }, { label: "y = −x + c", color: H.colors.accent2 }], H.W - 160, 28);

H.background();
const v = H.plot2d({ xMin: 0, xMax: 12, yMin: 0, yMax: 12 });
v.grid(); v.axes();
// Word problem: adult tickets (x) + child tickets (y).
//   total tickets:   x + y = T
//   total money:     a*x + y = M    (adult price a, child price 1)
const T = P.total, a = P.aprice, M = P.money;
// y = T - x   and   y = M - a*x
v.fn(x => T - x, { color: H.colors.accent, width: 3 });
v.fn(x => M - a * x, { color: H.colors.accent2, width: 3 });
H.text("Word problem: x + y = total,  a·x + y = money", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
// subtract: (a-1)x = M - T  ->  x adults, y children
if (Math.abs(a - 1) > 1e-6) {
  const xi = (M - T) / (a - 1), yi = T - xi;
  const pulse = 6 + 1.5 * Math.sin(t * 3);
  if (xi >= -1 && xi <= 13 && yi >= -1 && yi <= 13) {
    H.circle(v.X(xi), v.Y(yi), pulse, { fill: H.colors.warn });
    v.line(xi, 0, xi, yi, { color: H.colors.good, width: 1.5, dash: [3, 3] });
    v.line(0, yi, xi, yi, { color: H.colors.good, width: 1.5, dash: [3, 3] });
  }
  // animated marker sweeping line 1 to show "trying combinations"
  const xs = 6 + 5.5 * Math.sin(t * 0.6);
  v.dot(xs, T - xs, { r: 5, fill: H.colors.accent });
  H.text("x = " + xi.toFixed(1) + " adults,  y = " + yi.toFixed(1) + " children", 24, 52, { color: H.colors.good, size: 13 });
} else {
  H.text("adult price = 1: both equations identical — underdetermined", 24, 52, { color: H.colors.warn, size: 13 });
}
H.legend([{ label: "tickets: x+y=T", color: H.colors.accent }, { label: "money: a·x+y=M", color: H.colors.accent2 }], H.W - 195, 28);

H.background();
const w = H.W, hh = H.H;
const a = Math.round(P.a), b = Math.round(P.b);
const rel = Math.round(P.rel) % 4; // is / at least / at most / more than
const q = String.fromCharCode(34);
// "three times a number, <relation>, b"  ->  3x <rel> b
const relWords = ["is equal to", "is at least", "is at most", "is more than"];
const relSym   = ["=", ">=", "<=", ">"];
const sentence = q + a + " times a number " + relWords[rel] + " " + b + q;
const algebra  = a + " * x " + relSym[rel] + " " + b;
H.text("Translate a sentence to an equation / inequality", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Relationship words pick the symbol: 'is' -> = , 'at least' -> >= , 'at most' -> <= .", 24, 54, { color: H.colors.sub, size: 12 });
H.rect(50, 92, w - 100, 50, { fill: H.colors.panel, stroke: H.colors.grid, width: 1, radius: 10 });
H.text(sentence, 68, 123, { color: H.colors.ink, size: 18, weight: 600 });
const ay = 158 + 5 * Math.sin(t * 2.5);
H.arrow(w * 0.5, 146, w * 0.5, ay + 10, { color: H.colors.accent2, width: 3 });
H.rect(50, 188, w - 100, 50, { fill: "#13243f", stroke: H.colors.accent, width: 2, radius: 10 });
H.text(algebra, 68, 220, { color: H.colors.good, size: 24, weight: 700 });
// number line: solution of  a*x <rel> b  ->  x <rel'> b/a  (a assumed > 0)
const aa = a === 0 ? 1 : a;
const bound = b / aa;
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -1, yMax: 1, pad: 50 });
v.line(-10, 0, 10, 0, { color: H.colors.axis, width: 2 });
for (let k = -10; k <= 10; k += 2) { v.line(k, -0.12, k, 0.12, { color: H.colors.grid, width: 1.5 }); v.text(String(k), k, -0.45, { color: H.colors.sub, size: 11, align: "center" }); }
const cb = Math.max(-10, Math.min(10, bound));
// shade the solution region (skip for strict equality)
if (rel !== 0) {
  const goRight = rel === 1 || rel === 3; // at least / more than
  const x2 = goRight ? 10 : -10;
  v.line(cb, 0.18, x2, 0.18, { color: H.colors.good, width: 5 });
}
const open = rel === 3; // strict -> open circle
v.dot(cb, 0, { r: 7, fill: open ? H.colors.bg : H.colors.warn, stroke: H.colors.warn });
v.text("x " + relSym[rel] + " " + bound.toFixed(2), cb, 0.6, { color: H.colors.warn, size: 13, align: "center" });
// animated test point checking the inequality
const tx = 8 * Math.sin(t * 0.6);
const holds = rel === 0 ? Math.abs(aa * tx - b) < 0.3 : rel === 1 ? aa * tx >= b : rel === 2 ? aa * tx <= b : aa * tx > b;
v.dot(tx, -0.0, { r: 5, fill: holds ? H.colors.good : H.colors.sub });
H.text("a = " + a + "   b = " + b + "   ->   " + algebra + "   (x " + relSym[rel] + " " + bound.toFixed(2) + ")", 24, hh - 22, { color: H.colors.sub, size: 13 });

H.background();
const w = H.W, hh = H.H;
const n = Math.round(P.n);
const phrase = Math.round(P.phrase) % 4; // pick which verbal phrase to translate
const q = String.fromCharCode(34); // double-quote char for the English phrase
// Phrase bank: words -> algebra, with the operation keyword highlighted.
const bank = [
  { words: q + n + " more than a number" + q,         expr: "x + " + n, op: "more than -> +" },
  { words: q + n + " less than a number" + q,          expr: "x - " + n, op: "less than -> -" },
  { words: q + "the product of " + n + " and a number" + q, expr: n + " * x", op: "product -> *" },
  { words: q + "a number divided by " + n + q,         expr: "x / " + n, op: "divided by -> /" }
];
const cur = bank[phrase];
H.text("Translate words to algebra", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("'a number' becomes the variable x; the keyword picks the operation.", 24, 54, { color: H.colors.sub, size: 13 });
H.rect(50, 100, w - 100, 54, { fill: H.colors.panel, stroke: H.colors.grid, width: 1, radius: 10 });
H.text(cur.words, 70, 134, { color: H.colors.ink, size: 20, weight: 600 });
const ay = 175 + 6 * Math.sin(t * 2.5);
H.arrow(w * 0.5, 160, w * 0.5, ay + 14, { color: H.colors.accent2, width: 3 });
H.text(cur.op, w * 0.5 + 24, ay + 6, { color: H.colors.warn, size: 14 });
H.rect(50, 210, w - 100, 60, { fill: "#13243f", stroke: H.colors.accent, width: 2, radius: 10 });
H.text(cur.expr, 70, 250, { color: H.colors.good, size: 26, weight: 700 });
const keys = ["more than -> +", "less than -> -", "product -> *", "quotient -> /"];
for (let i = 0; i < keys.length; i++) {
  const yy = 320 + i * 26;
  const on = i === phrase;
  H.circle(64, yy - 4, 5, { fill: on ? H.colors.warn : H.colors.grid });
  H.text(keys[i], 80, yy, { color: on ? H.colors.ink : H.colors.sub, size: 14, weight: on ? 700 : 400 });
}
H.text("n = " + n + "    phrase #" + (phrase + 1) + "    ->    " + cur.expr, 24, hh - 22, { color: H.colors.sub, size: 14 });

H.background();
const a = P.a, b = P.b, c = P.c;
const degenerate = Math.abs(a) < 1e-6;            // a = 0 -> not a real two-step equation
const solRaw = degenerate ? 0 : (c - b) / a;       // true solution x (when it exists)
// Make the window always contain the solution AND the y=c line, so the
// intersection dot, its drop-line, and the readout always agree on-screen.
const span = Math.max(10, Math.abs(solRaw) + 2, Math.abs(c) + 2, Math.abs(b) + 2);
const v = H.plot2d({ xMin: -span, xMax: span, yMin: -span, yMax: span });
v.grid(); v.axes();
// line y = a x + b  (if a = 0 this is the horizontal line y = b)
v.fn(x => a * x + b, { color: H.colors.accent, width: 3 });
// target horizontal line y = c
v.line(-span, c, span, c, { color: H.colors.accent2, width: 2, dash: [6, 5] });
const phase = Math.floor((t % 9) / 3);
if (!degenerate) {
  // intersection = the solution x (guaranteed on-screen by the adaptive span)
  v.dot(solRaw, c, { r: 6 + Math.sin(t * 3), fill: H.colors.warn });
  v.line(solRaw, -span, solRaw, c, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
  v.text("x = " + solRaw.toFixed(2), solRaw + span * 0.03, c - span * 0.05, { color: H.colors.warn, size: 13, weight: 700 });
  // moving dot riding the line toward the solution
  const xs = solRaw * (0.5 + 0.5 * Math.sin(t * 0.8));
  v.dot(xs, a * xs + b, { r: 5, fill: H.colors.good });
}
const steps = degenerate
  ? [
      "0·x + " + b.toFixed(1) + " = " + c.toFixed(1),
      "no x term left:   " + b.toFixed(1) + " = " + c.toFixed(1),
      Math.abs(b - c) < 1e-6 ? "true for every x (identity)" : "false -> no solution"
    ]
  : [
      a.toFixed(1) + "x + " + b.toFixed(1) + " = " + c.toFixed(1),
      "subtract " + b.toFixed(1) + ":   " + a.toFixed(1) + "x = " + (c - b).toFixed(1),
      "divide by " + a.toFixed(1) + ":   x = " + solRaw.toFixed(2)
    ];
H.text("Two-step equation:  a*x + b = c", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("step " + (phase + 1) + " / 3:   " + steps[phase], 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "y = a x + b", color: H.colors.accent }, { label: "y = c", color: H.colors.accent2 }], H.W - 170, 28);

H.background();
const a = P.a, b = P.b, c = P.c, d = P.d;
const parallel = Math.abs(a - c) <= 1e-6;
const xs = parallel ? 0 : (d - b) / (a - c);
const ys = a * xs + b;
// Adapt the window so the intersection (the whole point of the demo) stays
// visible even for shallow slope differences that push it far out.
const span = Math.max(8, Math.abs(xs) + 2, Math.abs(ys) + 2);
const v = H.plot2d({ xMin: -span, xMax: span, yMin: -span, yMax: span });
v.grid(); v.axes();
// left side y = a x + b, right side y = c x + d; solution where they meet
v.fn(x => a * x + b, { color: H.colors.accent, width: 3 });
v.fn(x => c * x + d, { color: H.colors.accent2, width: 3 });
H.text("Variables on both sides:  a·x + b = c·x + d", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
if (!parallel) {
  v.line(xs, -span, xs, ys, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
  v.dot(xs, ys, { r: 7 + Math.sin(t * 3), fill: H.colors.good });
  v.text("x = " + xs.toFixed(2), xs + span * 0.03, ys + span * 0.08, { color: H.colors.good, size: 13 });
  H.text("collect x on one side: (a−c)·x = d−b   →   x = " + xs.toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
} else {
  H.text(Math.abs(b - d) < 1e-6 ? "same line — every x works (infinite solutions)" : "parallel — no x makes them equal (no solution)", 24, 52, { color: H.colors.warn, size: 13 });
}
// moving probe dot that sweeps along x, showing both sides' heights.
// Bound the sweep so BOTH heights stay inside the window at every frame.
const maxSlope = Math.max(Math.abs(a), Math.abs(c), 1e-6);
const xpAmp = Math.max(1, (span - Math.max(Math.abs(b), Math.abs(d)) - 1) / maxSlope);
const xp = Math.min(span - 2, xpAmp) * Math.sin(t * 0.6);
v.dot(xp, a * xp + b, { r: 5, fill: H.colors.accent });
v.dot(xp, c * xp + d, { r: 5, fill: H.colors.accent2 });
v.line(xp, a * xp + b, xp, c * xp + d, { color: H.colors.sub, width: 1, dash: [3, 3] });
H.legend([{ label: "left  a·x+b", color: H.colors.accent }, { label: "right  c·x+d", color: H.colors.accent2 }], H.W - 180, 28);

H.background();
const m = P.m, b = P.b;
const xint = Math.abs(m) > 1e-9 ? -b / m : NaN;
// Window includes the y-intercept (0,b) and the x-intercept (xint,0). Capped so
// a near-horizontal line doesn't shrink the picture to nothing; the line is
// drawn by fn so it stays visible regardless.
const span = Math.min(40, Math.max(8, (Number.isFinite(xint) ? Math.abs(xint) : 0) + 1.5, Math.abs(b) + 3));
const v = H.plot2d({ xMin: -span, xMax: span, yMin: -span, yMax: span });
v.grid(); v.axes();
v.fn(x => m * x + b, { color: H.colors.accent, width: 3 });
v.dot(0, b, { r: 7, fill: H.colors.good });
v.text("y-int (0, " + b.toFixed(1) + ")", span * 0.04, b + span * 0.08, { color: H.colors.good, size: 12 });
