H.background();
// Spherical mirror:  1/f = 1/do + 1/di,  with f = R/2
// Concave: f > 0 (converging). Convex: f < 0 (diverging).
const f = (Math.abs(P.f) < 0.2 ? (P.f < 0 ? -0.2 : 0.2) : P.f);  // focal length (cm)
const ho = P.ho;                                                  // object height (cm)
const af = Math.abs(f);
// Plot window adapts to |f| so the object, image, F and C stay on-screen for
// every focal length the slider can reach.
const v = H.plot2d({ xMin: -3.6 * af - 1, xMax: 2.4 * af + 1.5, yMin: -5, yMax: 5 });
v.grid(); v.axes();
// Object distance sweeps as a multiple of |f| (always outside F, so the real
// image stays finite and bounded) and moves through its whole range.
const do_ = af * (2.5 + 0.7 * Math.sin(t * 0.6));    // in [1.8|f|, 3.2|f|], always > |f|
const denom = (1 / f) - (1 / do_);
const di = Math.abs(denom) < 1e-5 ? 1e6 : 1 / denom; // image distance (cm)
const M = -di / do_;                                 // magnification
const hi = M * ho;                                   // image height (cm)
const R = 2 * f;                                      // radius of curvature
// Object & mirror sit in FRONT of the mirror = the NEGATIVE-x side; the mirror
// vertex is at the origin. For a concave mirror (f>0) F and C are real and lie
// in front, so they plot at x = -f and x = -R = -2f. (Convex flips the signs,
// putting F and C behind, as the negatives of negative f naturally give.)
const xF = -f, xC = -R;
// Mirror surface as a shallow arc that always bulges toward the FRONT (object
// side, -x): concave curves away from the object, convex toward it. Using |R|
// for the sag and the sign of f for the direction keeps the cup correct both ways.
const arc = [];
const sag = (f > 0 ? -1 : 1);   // concave opens toward -x; convex bulges toward -x
for (let yy = -4; yy <= 4.001; yy += 0.2) arc.push([sag * (yy * yy) / (2 * Math.abs(R)), yy]);
v.path(arc, { color: H.colors.violet, width: 3 });
v.line(0, -4, 0, 4, { color: H.colors.grid, width: 1, dash: [3, 3] });
v.dot(xF, 0, { r: 5, fill: H.colors.good });         // focal point F
v.dot(xC, 0, { r: 4, fill: H.colors.axis });         // center of curvature C
// Object arrow at x = -do_, image arrow at x = -di (real in front, virtual behind).
const xi = -di;
v.arrow(-do_, 0, -do_, ho, { color: H.colors.accent, width: 3 });
v.arrow(xi, 0, xi, hi, { color: H.colors.warn, width: 3 });
// Ray 1: parallel to axis to the mirror, then reflects THROUGH F.
// Object tip, mirror point (0,ho), F=(-f,0) and the image tip are colinear, so
// the segment (0,ho)->(xi,hi) genuinely passes through F.
v.line(-do_, ho, 0, ho, { color: H.colors.yellow, width: 1.5 });
v.line(0, ho, xi, hi, { color: H.colors.yellow, width: 1.5, dash: di < 0 ? [4, 4] : null });
// Ray 2: aimed at the center of curvature C; it strikes the mirror along the
// radius and reflects straight back on itself. Object tip, C and image tip are
// colinear, so this single line through C reaches the image tip.
v.line(-do_, ho, xi, hi, { color: H.colors.accent2, width: 1.5, dash: di < 0 ? [4, 4] : null });
v.dot(-do_, ho, { r: 5, fill: H.colors.accent });
v.dot(xi, hi, { r: 5, fill: H.colors.warn });
H.text(f > 0 ? "Concave mirror:  1/f = 1/do + 1/di" : "Convex mirror:  1/f = 1/do + 1/di", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f=" + f.toFixed(1) + "cm  do=" + do_.toFixed(1) + "  di=" + di.toFixed(1) + "  M=" + M.toFixed(2) + (di > 0 ? "  real/inverted" : "  virtual/upright"), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "object", color: H.colors.accent }, { label: "image", color: H.colors.warn }, { label: "F", color: H.colors.good }], H.W - 150, 28);

H.background();
const w = H.W, h = H.H;
const f = (Math.abs(P.f) < 0.2 ? (P.f<0?-0.2:0.2) : P.f);   // focal length cm (>0 converging, <0 diverging)
const dobj = Math.max(0.5, P.dobj);                          // object distance cm (left of lens)
const hobj = P.hobj;                                         // object height cm
// Thin lens: 1/f = 1/do + 1/di  ->  di = 1/(1/f - 1/do)
const invDi = (1/f) - (1/dobj);
const di = Math.abs(invDi) < 1e-6 ? 1e6 : 1/invDi;           // image distance cm (+ right/real, - left/virtual)
const M = -di/dobj;                                          // magnification
const himg = M*hobj;
const conv = f > 0;
H.text("Thin lens:  1/f = 1/do + 1/di", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f = " + f.toFixed(1) + " cm (" + (conv?"converging":"diverging") + ")   do = " + dobj.toFixed(1) + " cm   di = " + (Math.abs(di)>9e5?"infinity":di.toFixed(1)+" cm") + "   M = " + M.toFixed(2), 24, 52, { color: H.colors.sub, size: 12 });
// Optical axis and lens at centre. Map cm -> px about lens at x=cx.
const cx = w*0.5, axY = h*0.56;
const sc = H.clamp(180/Math.max(dobj, Math.abs(f)*2, Math.abs(di)>9e5?dobj:Math.abs(di)), 2, 40); // cm->px
const PX = (cm) => cx + cm*sc;     // +cm to the right
const PY = (cm) => axY - cm*sc;
H.line(40, axY, w-40, axY, { color: H.colors.axis, width: 1 });
// Lens drawn as a vertical lens shape (converging: convex; diverging: concave).
const lh = Math.min(h*0.30, 150);
if (conv){
  H.path([[cx, axY-lh],[cx+14, axY],[cx, axY+lh]], { color: H.colors.accent, width: 2 });
  H.path([[cx, axY-lh],[cx-14, axY],[cx, axY+lh]], { color: H.colors.accent, width: 2 });
} else {
  H.path([[cx-9,axY-lh],[cx+9,axY-lh],[cx+3,axY],[cx+9,axY+lh],[cx-9,axY+lh],[cx-3,axY],[cx-9,axY-lh]], { color: H.colors.accent, width: 2 });
}
// Focal points at +-f on the axis.
H.circle(PX(f), axY, 4, { fill: H.colors.violet });
H.circle(PX(-f), axY, 4, { fill: H.colors.violet });
H.text("F", PX(f)-4, axY+18, { color: H.colors.violet, size: 12 });
H.text("F'", PX(-f)-4, axY+18, { color: H.colors.violet, size: 12 });
// Object: an upright arrow at x = -do.
const ox = PX(-dobj);
H.arrow(ox, axY, ox, PY(hobj), { color: H.colors.good, width: 3 });
// Three principal rays from object tip ( otx, oty) to build the image.
const otx = ox, oty = PY(hobj);
// Ray 1: parallel to axis, then through F (far side) for converging.
H.line(otx, oty, cx, oty, { color: H.colors.warn, width: 1.5 });
// Image tip from the lens equation.
const imgx = PX(di>9e5?dobj:di), imgy = PY(himg);
if (Math.abs(di) < 9e5){
  // refracted ray 1 continues toward image tip
  H.line(cx, oty, imgx, imgy, { color: H.colors.warn, width: 1.5 });
  // Ray 2: straight through lens centre (undeviated).
  H.line(otx, oty, imgx, imgy, { color: H.colors.accent2, width: 1.5, dash: [4,4] });
  // Image arrow.
  const real = di > 0;
  H.arrow(imgx, axY, imgx, imgy, { color: real?H.colors.yellow:H.colors.sub, width: 3, dash: real?null:[5,5] });
  H.text(real?"real image":"virtual image", imgx + (imgx>cx?8:-90), imgy - 6, { color: real?H.colors.yellow:H.colors.sub, size: 12 });
}
// Animated photon riding ray 2 (object tip -> through centre -> image side).
const per = 2.4, ph = (t%per)/per;
let dx, dy;
if (Math.abs(di) < 9e5){
  if (ph<0.5){ const u=ph/0.5; dx=H.lerp(otx,cx,u); dy=H.lerp(oty,axY,u);} 
  else { const u=(ph-0.5)/0.5; dx=H.lerp(cx,imgx,u); dy=H.lerp(axY,imgy,u);} 
} else { const u=ph; dx=H.lerp(otx,cx,u); dy=H.lerp(oty,oty,u); }
H.circle(dx, dy, 5, { fill: H.colors.yellow });
H.legend([{label:"object", color:H.colors.good},{label:"image", color:H.colors.yellow},{label:"focal F", color:H.colors.violet}], w-160, 28);

H.background();
// Double-slit interference:  d * sin(theta) = m * lambda   (bright fringes)
// On a distant screen, fringe spacing  dy = lambda * L / d.
const v = H.plot2d({ xMin: -30, xMax: 30, yMin: 0, yMax: 1.25 });
v.grid(); v.axes();
const lam = P.lambda;     // wavelength (nm)
const d = P.d;            // slit separation (micrometers)
const L = P.L;            // slit-to-screen distance (m)
// Position on screen in mm; theta small so sin(theta) ~ y/L.
const lam_m = lam * 1e-9, d_m = d * 1e-6, L_m = L;
function intensity(y_mm) {
  const y = y_mm * 1e-3;
  const theta = Math.atan2(y, L_m);
  const phi = Math.PI * d_m * Math.sin(theta) / lam_m;  // half phase diff
  const c = Math.cos(phi);
  return c * c;   // I/Imax = cos^2(pi d sin / lambda)
}
v.fn(intensity, { color: H.colors.accent, width: 2.5, steps: 400 });
// Fringe spacing (mm): dy = lambda L / d.
const dy = lam_m * L_m / d_m * 1e3;
// Mark the central + first few bright fringes and sweep a probe.
for (let m = -3; m <= 3; m++) {
  const ym = m * dy;
  if (Math.abs(ym) <= 30) v.line(ym, 0, ym, 1, { color: H.colors.good, width: 1, dash: [4, 4] });
}
const yp = 25 * Math.sin(t * 0.7);
v.dot(yp, intensity(yp), { r: 6, fill: H.colors.warn });
v.line(yp, 0, yp, intensity(yp), { color: H.colors.warn, width: 1, dash: [2, 3] });
H.text("Double slit:  d·sin θ = m·λ", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("λ=" + lam.toFixed(0) + "nm  d=" + d.toFixed(1) + "µm  L=" + L.toFixed(1) + "m  →  fringe spacing Δy=" + dy.toFixed(2) + "mm", 24, 52, { color: H.colors.sub, size: 13 });
H.text("y = " + yp.toFixed(1) + " mm,   I/Imax = " + intensity(yp).toFixed(2), 24, 74, { color: H.colors.warn, size: 13 });
H.legend([{ label: "intensity", color: H.colors.accent }, { label: "bright fringes", color: H.colors.good }], H.W - 180, 28);

H.background();
// Single-slit diffraction:  a * sin(theta) = m * lambda  (DARK fringes, m=±1,±2,…)
// Intensity:  I/I0 = (sin(beta)/beta)^2,  beta = pi * a * sin(theta) / lambda.
const v = H.plot2d({ xMin: -40, xMax: 40, yMin: 0, yMax: 1.2 });
v.grid(); v.axes();
const lam = P.lambda;   // wavelength (nm)
const a = P.a;          // slit width (micrometers)
const L = P.L;          // slit-to-screen distance (m)
const lam_m = lam * 1e-9, a_m = a * 1e-6, L_m = L;
function intensity(y_mm) {
  const y = y_mm * 1e-3;
  const theta = Math.atan2(y, L_m);
  const beta = Math.PI * a_m * Math.sin(theta) / lam_m;
  if (Math.abs(beta) < 1e-6) return 1;     // limit sinc^2 -> 1
  const s = Math.sin(beta) / beta;
  return s * s;
}
v.fn(intensity, { color: H.colors.accent, width: 2.5, steps: 500 });
// First-minimum position (mm): a sin(theta)=lambda -> y1 ~ lambda L / a.
const y1 = lam_m * L_m / a_m * 1e3;
for (let m = -3; m <= 3; m++) {
  if (m === 0) continue;
  const ym = m * y1;
  if (Math.abs(ym) <= 40) v.line(ym, 0, ym, 0.25, { color: H.colors.warn, width: 1, dash: [4, 4] });
}
const yp = 34 * Math.sin(t * 0.6);
v.dot(yp, intensity(yp), { r: 6, fill: H.colors.good });
v.line(yp, 0, yp, intensity(yp), { color: H.colors.good, width: 1, dash: [2, 3] });
H.text("Single slit:  a·sin θ = m·λ  (dark fringes)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("λ=" + lam.toFixed(0) + "nm  a=" + a.toFixed(1) + "µm  L=" + L.toFixed(1) + "m  →  central width 2y₁=" + (2 * y1).toFixed(1) + "mm", 24, 52, { color: H.colors.sub, size: 13 });
H.text("y = " + yp.toFixed(1) + " mm,   I/I0 = " + intensity(yp).toFixed(3), 24, 74, { color: H.colors.good, size: 13 });
H.legend([{ label: "intensity (sinc²)", color: H.colors.accent }, { label: "first minima", color: H.colors.warn }], H.W - 200, 28);

H.background();
// Polarization — Malus's law:  I = I0 * cos^2(theta)
