H.arrow(bx, py, bx, py + 18 + Wt * 0.35, { color: H.colors.warn, width: 3, head: 10 });
H.text("mg", bx + 8, py + 26, { color: H.colors.warn, size: 12 });
const r = 11 + m * 1.2;
H.circle(bx, py, r, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
const PEmax = m * g * hmax || 1;
const barX = w * 0.84, barTop = topY, barH = groundY - topY;
H.rect(barX, barTop, 26, barH, { stroke: H.colors.grid, width: 1.5 });
