H.text("PE", barX + 2, barTop - 8, { color: H.colors.sub, size: 12 });
H.text("Gravitational PE:  PE = m·g·h", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(1) + " kg    g = 9.8 m/s²    h = " + height.toFixed(2) + " m    PE = " + PE.toFixed(1) + " J", 24, 54, { color: H.colors.sub, size: 13 });

H.background();
const k = P.k, A = P.A;
